#include "state.h"
#include <cmath>
#include <limits>
#include <regex>
#include <set>
namespace mt2mp::game::live_host_state {
namespace {
using json=nlohmann::json;
bool fail(std::string& e,const std::string& s){e=s;return false;}
bool uuid(const std::string& s){static const std::regex r("[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}");return std::regex_match(s,r);}
void exact(const json& j,std::initializer_list<const char*> names){if(!j.is_object()||j.size()!=names.size())throw std::runtime_error("live frame exact object fields required");for(const auto* n:names)if(!j.contains(n))throw std::runtime_error(std::string("live frame missing field: ")+n);}
uint64_t u64(const json& j){if(!j.is_number_integer()||(!j.is_number_unsigned()&&j.get<int64_t>()<0))throw std::runtime_error("live frame uint64 required");return j.get<uint64_t>();}
int32_t i32(const json& j){if(!j.is_number_integer()||(j.is_number_unsigned()?j.get<uint64_t>()>uint64_t(INT32_MAX):j.get<int64_t>()<INT32_MIN||j.get<int64_t>()>INT32_MAX))throw std::runtime_error("live frame int32 required");return j.get<int32_t>();}
template<size_t N>void ints(const json& j,std::array<int32_t,N>& out){if(!j.is_array()||j.size()!=N)throw std::runtime_error("live frame exact scalar array size required");for(size_t i=0;i<N;++i)out[i]=i32(j.at(i));}
bool same_pin(const Pin& a,const Pin& b){auto left=a,right=b;left.values={};right.values={};return left==right;}
}
bool valid(const Frame& f,std::string& e){if(!f.session||!f.epoch||!f.source_generation||!f.revision||!uuid(f.snapshot)||(!f.for_action.empty()&&!uuid(f.for_action)))return fail(e,"live frame authority origin/revision/UUID invalid");
    if((f.selected!=0&&f.selected!=1&&f.selected!=3&&f.selected!=9)||!std::isfinite(f.pause)||f.pause<0||f.pause>1)return fail(e,"live frame Host scale pair invalid");
    const auto& c=f.values.calendar;const int32_t day=c[3];if(day<0||c[4]<0||c[5]!=7||c[0]!=day/84+1||c[1]!=(day/7)%12+1||c[2]!=day%7+1)return fail(e,"live frame native calendar decomposition invalid");
    if(f.values.record[0]!=day||f.values.record[1]!=f.values.cash)return fail(e,"live frame CurrentRecord day/cash differs from Clock/Business");
    if(f.network&&!network::valid(*f.network,e))return false;
    if(f.tutorial&&!tutorial_replication::valid(*f.tutorial,e))return false;
    for(const auto& line:f.values.lines)if(line[0]<0)return fail(e,"live frame negative category count");e.clear();return true;}
std::array<int32_t,scalar_count> scalars(const Values& v){std::array<int32_t,scalar_count> out{};size_t at=0;for(auto n:v.calendar)out[at++]=n;out[at++]=v.cash;for(auto n:v.record)out[at++]=n;for(auto row:v.lines)for(auto n:row)out[at++]=n;return out;}
action_session::Ledger ledger(const Values& v){action_session::Ledger out;out.cash=v.cash;out.flat_day=v.calendar[3];out.record_present=1;out.record_day=v.record[0];out.record_cash=v.record[1];out.record_income=v.record[3];out.record_expense=v.record[4];for(size_t i=0;i<20;++i){out.line_counts[i]=v.lines[i][0];out.line_income[i]=v.lines[i][1];}return out;}
bool encode(const Frame& f,std::vector<uint8_t>& out,std::string& e){out.clear();if(!valid(f,e))return false;try{json j={{"schema",9},{"kind","host_state"},{"session",f.session},{"epoch",f.epoch},{"source_generation",f.source_generation},{"revision",f.revision},{"base_action_revision",f.base_action_revision},{"time_revision",f.time_revision},{"snapshot_uuid",f.snapshot},{"for_action",f.for_action},{"selected",f.selected},{"pause",f.pause},{"network",f.network?network::encode(*f.network):json(nullptr)},{"tutorial",f.tutorial?tutorial_replication::encode(*f.tutorial):json(nullptr)},{"values",{{"calendar",f.values.calendar},{"cash",f.values.cash},{"record",f.values.record},{"lines",f.values.lines}}}};const auto bytes=j.dump();if(bytes.size()>max_frame_payload)return fail(e,"live frame exceeds 65536-byte Channel9 transport bound");out.assign(bytes.begin(),bytes.end());e.clear();return true;}catch(const std::exception& x){return fail(e,std::string("live frame encode: ")+x.what());}}
bool decode(const uint8_t* data,size_t n,Frame& out,std::string& e){out={};if(!data||!n||n>max_frame_payload)return fail(e,"live frame 65536-byte Channel9 length bound invalid");try{std::vector<std::set<std::string>> fields;const auto j=json::parse(data,data+n,[&](int depth,json::parse_event_t event,json& value){if(depth>5)throw std::runtime_error("live frame nesting depth exceeds5");if(event==json::parse_event_t::object_start)fields.emplace_back();if(event==json::parse_event_t::key&&!fields.back().insert(value.get<std::string>()).second)throw std::runtime_error("duplicate live frame field");if(event==json::parse_event_t::object_end)fields.pop_back();return true;});
    exact(j,{"schema","kind","session","epoch","source_generation","revision","base_action_revision","time_revision","snapshot_uuid","for_action","selected","pause","network","tutorial","values"});if(u64(j.at("schema"))!=9||j.at("kind")!="host_state")throw std::runtime_error("not a schema9 host_state frame");Frame f;f.session=u64(j.at("session"));f.epoch=u64(j.at("epoch"));f.source_generation=u64(j.at("source_generation"));f.revision=u64(j.at("revision"));f.base_action_revision=u64(j.at("base_action_revision"));f.time_revision=u64(j.at("time_revision"));f.snapshot=j.at("snapshot_uuid").get<std::string>();f.for_action=j.at("for_action").get<std::string>();if(!j.at("selected").is_number()||!j.at("pause").is_number())throw std::runtime_error("live frame numeric scale pair required");f.selected=j.at("selected").get<float>();f.pause=j.at("pause").get<float>();if(!j.at("network").is_null()){network::State nodes;if(!network::decode(j.at("network"),nodes,e))return false;f.network=std::move(nodes);}if(!j.at("tutorial").is_null()){tutorial_replication::State tutorial;if(!tutorial_replication::decode(j.at("tutorial"),tutorial,e))return false;f.tutorial=std::move(tutorial);}const auto& v=j.at("values");exact(v,{"calendar","cash","record","lines"});ints(v.at("calendar"),f.values.calendar);f.values.cash=i32(v.at("cash"));ints(v.at("record"),f.values.record);const auto& rows=v.at("lines");if(!rows.is_array()||rows.size()!=20)throw std::runtime_error("live frame requires exactly20 categories");for(size_t i=0;i<20;++i)ints(rows.at(i),f.values.lines[i]);if(!valid(f,e))return false;out=std::move(f);e.clear();return true;
    }catch(const std::exception& x){return fail(e,std::string("live frame decode: ")+x.what());}}
Admission admit(uint64_t sender,const Context& c,uint64_t epoch,uint64_t generation,const Frame* last,const Frame& f,uint64_t action_revision,uint64_t time_revision,bool pending,std::string& e){if(!valid(f,e))return Admission::Rejected;if(c.role!=action_session::Role::Client||sender!=c.host_peer||sender!=1||!(c.peer_mask&1u)||f.session!=c.session||f.snapshot!=c.snapshot_uuid||f.epoch!=epoch||f.source_generation!=generation){fail(e,"live frame authenticated Host/session/snapshot/source binding differs");return Admission::Rejected;}
    if(last&&f.revision==last->revision){if(f==*last){e.clear();return Admission::Duplicate;}fail(e,"live frame same revision conflicting payload");return Admission::Rejected;}
    if(last&&f.revision<last->revision){e="live frame stale; no stores";return Admission::Stale;}
    if(!f.for_action.empty()||pending||f.base_action_revision>action_revision||f.time_revision>time_revision){e="live frame waits for existing action/time Controller order; no stores";return Admission::Wait;}
    if(f.base_action_revision<action_revision||f.time_revision<time_revision){e="live frame superseded by action/time authority; no stores";return Admission::Stale;}e.clear();return Admission::New;}
Admission admit_before_result(uint64_t sender,const Context& c,uint64_t epoch,uint64_t generation,const Frame* last,const Frame& f,const action_session::Message& result,uint64_t previous,uint64_t time_revision,std::string& e){
    if(result.kind!=action_session::Kind::HostResult||result.outcome!=action_session::Outcome::Confirmed||previous==UINT64_MAX||result.revision!=previous+1||result.session!=c.session||result.request.snapshot_uuid!=c.snapshot_uuid||f.for_action.empty()||f.for_action!=result.request.action_uuid||f.base_action_revision!=previous||ledger(f.values)!=result.evidence.before){fail(e,"live before-result exact UUID/previous revision/authority ledger differs");return Admission::Rejected;}
    Frame ordinary=f;ordinary.for_action.clear();const auto outcome=admit(sender,c,epoch,generation,nullptr,ordinary,previous,time_revision,false,e);if(outcome!=Admission::New)return outcome;
    if(last&&f.revision<=last->revision){if(f==*last){e.clear();return Admission::Duplicate;}fail(e,"live before-result stale/conflicting retained frame");return Admission::Rejected;}e.clear();return Admission::New;
}
ApplyReceipt apply(Port& io,const Pin& expected,const Frame& target){ApplyReceipt r;try{if(!valid(target,r.cause))return r;Pin actual;if(!io.read(actual,r.cause))return r;
    if(actual.context.role!=action_session::Role::Client||actual.selected!=0||actual!=expected||actual.context.session!=target.session||actual.context.snapshot_uuid!=target.snapshot||actual.common_epoch!=target.epoch){r.cause="live frame actual Client/nativeClock0/expected local pin/common epoch differs";return r;}
    if(target.values.calendar[3]!=actual.values.calendar[3]||target.values.record[0]!=actual.values.record[0]){r.cause="live frame rollover requires native History append and closed-day receipt; retagging existing CurrentRecord is rejected before stores";return r;}
    const auto before=scalars(actual.values),after=scalars(target.values);for(size_t i=0;i<scalar_count;++i){if(before[i]==after[i])continue;r.attempted=true;++r.attempted_stores;if(!io.store(expected,i,before[i],after[i],r.cause)){r.unknown=true;r.cause="live frame scalar store unknown slot="+std::to_string(i)+" original="+r.cause;return r;}++r.completed_stores;}
    Pin observed;if(!io.read(observed,r.cause)||!same_pin(expected,observed)||observed.values!=target.values){r.unknown=r.attempted;if(r.cause.empty())r.cause="live frame full52-slot readback or pinned native owners differ";return r;}r.actual=observed.values;r.actual_present=true;r.confirmed=true;r.duplicate=!r.attempted;return r;
    }catch(const std::exception& x){r.cause=std::string("live frame apply exception: ")+x.what();r.unknown=r.attempted;return r;}catch(...){r.cause="live frame apply non-standard exception";r.unknown=r.attempted;return r;}}
}
